style.css:
@-moz-document url-prefix("https://open.spotify.com/") {
body, html {
    background: url("https://files.oaiusercontent.com/file-VtiE9xPptmULurTrPCfTVF?response-content-disposition=inline%3B+filename%3D%22gif%20banner%20discord.jpeg%22&Expires=4749189436&Signature=YOUR_IMAGE_SIGNATURE_HERE") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #660033 !important;
  }

  .Root__main-view,
  .main-view-container__scroll-node-child,
  .main-topBar-background,
  .main-navBar-navBar {
    background-color: rgba(255, 240, 245, 0.75) !important;
    backdrop-filter: blur(8px);
  }

  .main-rootlist-rootlistItemLink,
  .main-navBar-navBarLink {
    color: #b30059 !important;
  }

  .main-rootlist-rootlistItemLink:hover,
  .main-navBar-navBarLink:hover {
    background-color: rgba(255, 204, 224, 0.8) !important;
    color: #ff3399 !important;
  }

  .main-nowPlayingBar-container {
    background-color: rgba(255, 214, 238, 0.9) !important;
  }

  ::-webkit-scrollbar-thumb {
    background: #ff99cc !important;
  }
}
